owned_rules:
table ip dns_policy_poc {
	set pods {
		type ifname . ipv4_addr
		elements = { "eni3b790ef6f68" . 10.244.0.8 }
	}

	chain rawpre {
		type filter hook prerouting priority raw - 10; policy accept;
		iifname . ip saddr @pods meta l4proto { tcp, udp } th dport 53 notrack
	}

	chain rawout {
		type filter hook output priority raw - 10; policy accept;
		oifname . ip daddr @pods meta l4proto { tcp, udp } th sport 53 notrack
	}

	chain transparent {
		type filter hook prerouting priority mangle; policy accept;
		iifname . ip saddr @pods meta l4proto { tcp, udp } th dport 53 tproxy to :50052 meta mark set meta mark | 0x20000000 accept
	}
}
